code_snippets.parse_list:
def parse(self, response):
    items = response.css('body > div.content > div.listing > ul > li')
    for item in items:
        detail_url = item.css('a::attr(href)').get()
        if detail_url:
            yield response.follow(detail_url, self.parse_detail)

code_snippets.parse_detail:
def parse_detail(self, response):
    yield {
        'title': response.css('h1.page-title::text, div.detail-header > h1::text').get(),
        'author': response.css('div.authors > span.author-name::text').getall(),
        'publication_date': response.css('div.pub-date::text').get(),
        'abstract': response.css('div.abstract::text').get(),
        'pdf_link': response.css('a[href$=".pdf"]::attr(href)').get(),
        'supplementary_materials': response.css('a.supplementary-download::attr(href)').getall()
    }
